<template><StatePanel v-if="pending" kind="loading" title="Loading service" message="Checking service details." /><StatePanel v-else-if="error || !identity || !service" kind="error" title="Service unavailable" message="This service is not published." /><StorefrontFrame v-else :identity="identity" :navigation="navigation" :base="base"><div class="grid gap-10 lg:grid-cols-[minmax(0,1fr)_22rem]"><article><h1 class="display-face text-5xl font-semibold tracking-[-0.03em]">{{ service.name }}</h1><p class="mt-5 max-w-3xl text-lg leading-8 text-muted-foreground">{{ service.description || service.summary }}</p><dl class="mt-8 divide-y border-y text-sm"><div class="flex justify-between gap-4 py-4"><dt class="text-muted-foreground">Duration</dt><dd class="font-bold">{{ service.duration_minutes }} minutes</dd></div><div class="flex justify-between gap-4 py-4"><dt class="text-muted-foreground">Price</dt><dd class="font-bold">{{ money(service.base_price) }}</dd></div><div class="flex justify-between gap-4 py-4"><dt class="text-muted-foreground">Capacity</dt><dd class="font-bold">Up to {{ service.capacity }}</dd></div></dl></article><aside class="border-t pt-6 lg:border-l lg:border-t-0 lg:pl-8 lg:pt-0"><h2 class="font-bold">Ready to book?</h2><p class="mt-3 text-sm leading-6 text-muted-foreground">Availability is checked again transactionally when you confirm, preventing overlapping or over-capacity bookings.</p><ButtonAnchor  :href="`${base}/booking?service=${service.slug}`" class="mt-6 w-full">See available times</ButtonAnchor></aside></div></StorefrontFrame></template>
<script setup>
definePageMeta({ layout: 'storefront' }); const route = useRoute(); const { identity, navigation, pending, error, baseURL, siteBase: base } = useStorefrontContext(route.params.slug); const { data: service } = useAsyncData(`service:${route.params.slug}:${route.params.serviceSlug}`, () => $fetch(`public/${route.params.slug}/catalog/${route.params.serviceSlug}/`, { baseURL })); const money = (value) => new Intl.NumberFormat('en-PH', { style: 'currency', currency: identity.value?.currency || 'PHP' }).format(Number(value || 0))
const requestUrl = useRequestURL()
useHead(() => service.value && identity.value ? {
  title: `${service.value.name} | ${identity.value.display_name}`,
  meta: [{ name: 'description', content: service.value.summary || service.value.description?.slice(0, 180) }, { property: 'og:title', content: service.value.name }, { property: 'og:description', content: service.value.summary || service.value.description?.slice(0, 180) }],
  link: [{ rel: 'canonical', href: `${requestUrl.origin}${requestUrl.pathname}` }],
  script: [{ type: 'application/ld+json', innerHTML: JSON.stringify({ '@context': 'https://schema.org', '@type': 'Service', name: service.value.name, description: service.value.summary || service.value.description, provider: { '@type': 'Organization', name: identity.value.display_name } }).replaceAll('<', '\\u003c') }],
} : {})
</script>
